</style></head><body><header class="top"><div class="brand"><span class="mark" aria-hidden="true">✦</span><span>eRPH Pro</span></div><a href="{{ route('school.admin') }}">Back to administration</a></header><main class="main"><span class="eyebrow">{{ $school->subdomain }} / school settings</span><div class="heading"><h1>School configuration</h1><p class="muted">These values belong to {{ $school->name }}. Other schools can use different academic calendars and lesson times.</p></div>@if(session('status'))<div class="notice">{{ session('status') }}</div>@endif<section class="card"><h2>Academic system</h2><form method="post" action="{{ route('school.settings.update') }}">@csrf @method('put')<div class="grid"><label>Academic year<input type="number" name="academic_year" value="{{ $settings->academic_year }}" required></label><label>Total weeks<input type="number" name="total_weeks" value="{{ $settings->total_weeks }}" required></label><label>Active week<input type="number" name="active_week" value="{{ $settings->active_week }}" required></label><label>Submission weekday<select name="submission_weekday">@foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $day)<option value="{{ $day }}" @selected($settings->submission_weekday === $day)>{{ $day }}</option>@endforeach</select></label><label>Active week deadline<input type="date" name="active_week_deadline" value="{{ $settings->active_week_deadline?->format('Y-m-d') }}"></label></div><button class="button" type="submit">Save school settings</button></form></section><section class="card"><h2>Lesson time slots</h2><p class="muted">Add the actual periods used by this school. Teachers will use these values when preparing RPH.</p><form method="post" action="{{ route('school.settings.timetable.add') }}">@csrf<div class="grid"><label>Day<select name="day_of_week">@foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $day)<option>{{ $day }}</option>@endforeach</select></label><label>Label<input name="label" placeholder="Period 1 / Assembly"></label><label>Starts at<input type="time" name="starts_at" required></label><label>Ends at<input type="time" name="ends_at" required></label><label>Order<input type="number" name="sort_order" value="1" min="0"></label></div><button class="button" type="submit">Add time slot</button></form>@forelse($slots as $slot)<div class="slot"><strong>{{ $slot->day_of_week }} · {{ $slot->label ?: 'Lesson period' }}</strong><span>{{ substr($slot->starts_at, 0, 5) }} – {{ substr($slot->ends_at, 0, 5) }}</span></div>@empty<p class="muted">No lesson time slots configured yet.</p>@endforelse</section></main></body></html>
